package dev.kubejseditor;

import com.google.gson.*;
import dev.kubejseditor.recipe.compat.*;
import java.util.*;
import static dev.kubejseditor.recipe.compat.CompatDefinition.*;

public final class CompatibilityVerification {
    private static int checks;private static void check(boolean value,String message){if(!value)throw new AssertionError(message);checks++;}
    private static void fails(Runnable action,String message){try{action.run();}catch(RuntimeException expected){checks++;return;}throw new AssertionError(message);}
    private static JsonObject json(String text){return JsonParser.parseString(text).getAsJsonObject();}
    public static int run(){
        var mi=json("{type:'modern_industrialization:custom_machine',eu:25,duration:200,item_inputs:[{item:'minecraft:iron_ingot',amount:99,probability:0}],fluid_inputs:[{fluid:'minecraft:water',amount:9007199254740993}],item_outputs:[{item:'minecraft:gold_ingot',amount:2,components:{'minecraft:custom_data':{value:3}}}],other:{unmapped:true}}");
        var p=new RecipePresentation(mi,CompatDefinitions.machine(mi.get("type").getAsString()));check(p.validate().isEmpty(),"MI accepts precise integer fluid quantity above 2^53");check(p.bindings().size()==6,"MI item/fluid/output plus energy/time/conditions");var input=p.bindings().getFirst();check(p.item(input).get("count").getAsInt()==99,"MI amount is item quantity");check(p.item(input).get("chance").getAsInt()==0,"MI non-consumable input is probability zero");
        var edit=p.item(input);edit.addProperty("item","minecraft:diamond");p.writeItem(input,edit);check(mi.getAsJsonArray("item_inputs").get(0).getAsJsonObject().get("amount").getAsInt()==99,"MI replacement retains amount");check(mi.getAsJsonObject("other").get("unmapped").getAsBoolean(),"Unknown data retained");p.verifyRoundTrip(mi.deepCopy());checks++;
        var fluid=p.bindings().stream().filter(RecipePresentation.Binding::fluid).findFirst().orElseThrow();check(p.item(fluid).get("amount").getAsString().equals("9007199254740993"),"Fluid count never coerced through double or ItemStack");
        var invalid=p.item(input);invalid.addProperty("count",1.5);p.writeItem(input,invalid);check(!p.validate().isEmpty(),"Non-integer quantity rejected");p.writeItem(input,edit);
        var forge=json("{type:'forbidden_arcanus:ritual',inputs:[{amount:2,ingredient:{item:'minecraft:coal'},custom:5},{amount:2,ingredient:{item:'minecraft:diamond'}}],main_ingredient:{item:'minecraft:redstone'},result:{type:'forbidden_arcanus:create_item',result_item:{id:'minecraft:emerald',count:1}},essences:{aureal:100,blood:2000,souls:5},forge_tier:1}");
        var f=new RecipePresentation(forge,CompatDefinitions.ritual(forge));check(f.validate().isEmpty(),"Ritual grouped ingredients valid");var outer=f.bindings().stream().filter(b->!b.field().expand.isBlank()).toList();check(outer.size()==4,"Two groups expand to four physical pedestals");check(f.item(outer.getFirst()).get("count").getAsInt()==1,"Pedestal amount is not stack count");var diamond=f.item(outer.getFirst());diamond.addProperty("item","minecraft:gold_ingot");f.writeItem(outer.getFirst(),diamond);check(forge.getAsJsonArray("inputs").size()==3,"Editing one occurrence splits grouped ingredient");check(forge.getAsJsonArray("inputs").get(1).getAsJsonObject().getAsJsonObject("ingredient").get("item").getAsString().equals("minecraft:coal"),"Sibling pedestal unchanged");check(forge.getAsJsonArray("inputs").get(0).getAsJsonObject().get("custom").getAsInt()==5,"Split preserves unknown entry fields");
        var coal=f.item(f.bindings().getFirst());coal.addProperty("item","minecraft:coal");f.writeItem(f.bindings().getFirst(),coal);check(forge.getAsJsonArray("inputs").size()==2,"Equivalent adjacent groups compact without changing count");f.verifyRoundTrip(forge.deepCopy());checks++;
        forge.getAsJsonArray("inputs").get(0).getAsJsonObject().addProperty("amount",7);check(!f.validate().isEmpty(),"More than eight pedestals rejected independently of native list length");forge.getAsJsonArray("inputs").get(0).getAsJsonObject().addProperty("amount",2);
        for(String result:List.of("create_item","transmute_input","upgrade_tier")){CompatDefinitions.switchRitualResult(forge,"forbidden_arcanus:"+result);var v=new RecipePresentation(forge,CompatDefinitions.ritual(forge));check(v.validate().isEmpty(),"Native result mode supported: "+result);v.verifyRoundTrip(forge.deepCopy());checks++;}
        check(CompatDefinitions.ritual(forge).fields.stream().filter(b->b.role==Role.RESOURCE).count()==4,"Four essence resources independent of fluid slots");
        var custom=json("{type:'unknown:machine',charge:{value:12345},feed:[{item:'minecraft:iron_ingot'},{item:'minecraft:coal'}],out:{id:'minecraft:gold_ingot',count:2},settings:{opaque:'retain'}}");var definition=new CompatDefinition("unknown:machine","confirmed");var a=definition.add("/feed","材料",Kind.ITEM,Role.INPUT);a.list=true;var o=definition.add("/out","结果",Kind.ITEM,Role.OUTPUT);o.quantity="count";var n=definition.add("/charge/value","电量",Kind.NUMBER,Role.RESOURCE);n.integer=true;n.unit="自定义单位";var generic=new RecipePresentation(custom,definition);check(generic.validate().isEmpty(),"Arbitrary serializer works with explicit mappings");var first=generic.bindings().getFirst();var item=generic.item(first);item.addProperty("item","minecraft:diamond");generic.writeItem(first,item);check(custom.getAsJsonArray("feed").get(0).getAsJsonObject().get("item").getAsString().equals("minecraft:diamond"),"Unknown mod edits mapped path");generic.verifyRoundTrip(custom.deepCopy());checks++;var dropped=custom.deepCopy();dropped.getAsJsonObject("charge").addProperty("value",0);fails(()->generic.verifyRoundTrip(dropped),"Codec dropping a mapped value must reject");
        var root=json("{'key/with~escape':{items:[1,2]}}");check(CompatJson.get(root,"/key~1with~0escape/items/1").getAsInt()==2,"Escaped pointers remain exact");CompatJson.set(root,"/key~1with~0escape/items/1",new JsonPrimitive(3));check(CompatJson.get(root,"/key~1with~0escape/items/1").getAsInt()==3,"Escaped pointer mutation");
        var layout=new LayoutMappings.Profile();layout.category="unknown:machine";layout.modVersion="1";layout.shape=CompatJson.shape(custom);layout.width=100;layout.height=80;layout.regions.add(new LayoutMappings.Region(first.key(),1,2,16,16));LayoutMappings.check(layout);checks++;check(LayoutMappings.matches(layout,layout.category,"1",layout.shape,100,80),"Manual layout restores same recipe shape");check(!LayoutMappings.matches(layout,layout.category,"2",layout.shape,100,80),"Mod version invalidates manual layout");check(!LayoutMappings.matches(layout,layout.category,"1",layout.shape,110,80),"Dimensions invalidate manual layout");custom.getAsJsonArray("feed").add(json("{item:'minecraft:paper'}"));check(!LayoutMappings.matches(layout,layout.category,"1",CompatJson.shape(custom),100,80),"Dynamic ingredient count invalidates static annotations");layout.regions.add(new LayoutMappings.Region("other",4,5,16,16));fails(()->LayoutMappings.check(layout),"Overlapping marks rejected");
        check(generic.editableBindings().stream().anyMatch(b->b.path().equals("/feed/-")),"Empty custom frames can bind a virtual append target");
        var mappedShape=CompatJson.mappingShape(custom);var extra=json("{item:'minecraft:paper'}");generic.appendItem(a,extra);check(CompatJson.mappingShape(custom).equals(mappedShape),"Confirmed data mapping serves different list lengths");check(custom.getAsJsonArray("feed").size()==4,"Shared append inserts native ingredient");
        var nested=json("{type:'other:fluid',supply:{ingredient:{fluid:'minecraft:water',type:'neoforge:single'},amount:250}}");var nestedDef=new CompatDefinition("other:fluid","confirmed");var nf=nestedDef.add("/supply","流体",Kind.FLUID,Role.INPUT);nf.quantity="amount";var np=new RecipePresentation(nested,nestedDef);var nb=np.bindings().getFirst();check(np.item(nb).get("amount").getAsInt()==250,"Nested sized fluid wrapper exposes fluid quantity");var nv=np.item(nb);nv.addProperty("amount",500);np.writeItem(nb,nv);check(nested.getAsJsonObject("supply").get("amount").getAsInt()==500,"Nested sized fluid writes quantity to its wrapper");np.verifyRoundTrip(nested.deepCopy());checks++;
        var component=json("{type:'other:component',material:{type:'neoforge:components',items:'minecraft:stone',components:{'minecraft:custom_data':{key:1}},strict:false}}");var cd=new CompatDefinition("other:component","confirmed");cd.add("/material","组件原料",Kind.ITEM,Role.INPUT);var cp=new RecipePresentation(component,cd);var omitted=component.deepCopy();omitted.getAsJsonObject("material").remove("strict");cp.verifyRoundTrip(omitted);checks++;
        var opaque=json("{type:'other:format',material:{item:'minecraft:stone',amount:99,chance:100}}");var od=new CompatDefinition("other:format","confirmed");od.add("/material","物品",Kind.ITEM,Role.INPUT);var op=new RecipePresentation(opaque,od);check(op.item(op.bindings().getFirst()).get("count").getAsInt()==1,"Unmapped amount is not guessed as item count");check(op.validate().isEmpty(),"Unmapped percentage is preserved without guessing 0..1 probability");
        var legacy=json("{type:'example:legacy',ingredients:[{ingredient:{item:'minecraft:iron_ingot'},count:3}],results:[{result:{id:'minecraft:gold_ingot',count:2},chance:0.5}],energy:1000,timing:{ticks:40}}");var legacyAdapter=new dev.kubejseditor.recipe.SimpleRecipeAdapter(legacy);var legacyView=legacyAdapter.presentation(legacy);check(legacyView.bindings().size()==4,"Legacy presentation includes slots and nested parameters");var lb=legacyView.bindings().getFirst();var lv=legacyView.item(lb);lv.addProperty("item","minecraft:copper_ingot");legacyView.writeItem(lb,lv);check(legacy.getAsJsonArray("ingredients").get(0).getAsJsonObject().get("count").getAsInt()==3,"Legacy presentation delegates sized wrapper quantity");var lo=legacyView.bindings().get(1);var le=legacyView.item(lo);le.addProperty("count",4);le.addProperty("chance",0.25);legacyView.writeItem(lo,le);check(legacy.getAsJsonArray("results").get(0).getAsJsonObject().get("chance").getAsDouble()==0.25,"Legacy presentation retains wrapper probability");legacyView.verifyRoundTrip(legacy.deepCopy());checks++;
        var alternatives=json("{type:'example:alternatives',input:{ingredient:[{item:'minecraft:iron_ingot'},{tag:'c:ingots/copper'}],count:3},output:{id:'minecraft:stone'}}");var ad=new CompatDefinition("example:alternatives","confirmed");ad.add("/input","OR 材料",Kind.ITEM,Role.INPUT).quantity="count";var ap=new RecipePresentation(alternatives,ad);check(ap.item(ap.bindings().getFirst()).getAsJsonArray("alternatives").size()==2,"OR alternatives remain a single semantic slot");check(ap.validate().isEmpty(),"OR ingredients validate without flattening their provenance");ap.verifyRoundTrip(alternatives.deepCopy());checks++;
        var jdte=json("{type:'jdte:infusion',input:{id:'minecraft:stone',count:2},fluid:{id:'minecraft:water',amount:250},output:{id:'minecraft:gold_ingot',count:1},energy:100}");var jp=new RecipePresentation(jdte,CompatDefinitions.jdteInfusion("jdte:infusion"));var jb=jp.bindings().get(1);var jv=jp.item(jb);jv.addProperty("amount",500);jp.writeItem(jb,jv);check(jdte.getAsJsonObject("fluid").get("id").getAsString().equals("minecraft:water")&&!jdte.getAsJsonObject("fluid").has("fluid"),"Native fluid stack retains its id representation");
        var bio=json("{type:'jdte:bio_factory',specimen:{item:'minecraft:egg'},inputs:[{ingredient:{item:'minecraft:stone'},count:0}],outputs:[{item:{id:'minecraft:gold_ingot',count:2},chance:0.5}],process_ticks:20,energy:100}");var bp=new RecipePresentation(bio,CompatDefinitions.jdteBioFactory("jdte:bio_factory",bio));check(bp.validate().isEmpty(),"Non-consumable native requirement remains count zero outside display projection");var bo=bp.bindings().stream().filter(RecipePresentation.Binding::output).findFirst().orElseThrow();var bv=bp.item(bo);bv.addProperty("count",4);bv.addProperty("chance",0.25);bp.writeItem(bo,bv);check(bio.getAsJsonArray("outputs").get(0).getAsJsonObject().getAsJsonObject("item").get("count").getAsInt()==4,"Nested native item output quantity is editable");bp.verifyRoundTrip(bio.deepCopy());checks++;
        var optionalDef=new CompatDefinition("other:optional","kubejs-schema");optionalDef.add("/absent","可选开关",Kind.BOOLEAN,Role.PARAMETER);var optionalView=new RecipePresentation(json("{type:'other:optional'}"),optionalDef);check(optionalView.editableBindings().isEmpty(),"Absent optional fields from another recipe are not shown as null controls");optionalDef.fields.getFirst().fallback=new JsonPrimitive(false);check(optionalView.editableBindings().size()==1,"Explicit optional defaults remain editable");
        var giant=json("{type:'generic:fixture',feed:{ingredient:{item:'minecraft:iron_ingot'},amount:20480},out:{item:{id:'minecraft:diamond',count:2},chance:0.5}}");var gd=new CompatDefinition("generic:fixture","jei-native");var gi=gd.add("/feed","原料",Kind.ITEM,Role.INPUT);CompatFields.shape(gi,giant.get("feed"));var go=gd.add("/out","产物",Kind.ITEM,Role.OUTPUT);go.probability="chance";CompatFields.shape(go,giant.get("out"));var gp=new RecipePresentation(giant,gd);check(gp.item(gp.bindings().getFirst()).get("count").getAsInt()==20480,"Large native quantity stays independent of ItemStack");var alternativeItems=new JsonArray();alternativeItems.add(json("{item:'minecraft:iron_ingot'}"));alternativeItems.add(json("{tag:'c:ingots/copper'}"));gp.writeAlternatives(gp.bindings().getFirst(),alternativeItems);check(giant.getAsJsonObject("feed").get("amount").getAsInt()==20480&&giant.getAsJsonObject("feed").get("ingredient").isJsonArray(),"OR changes only native ingredient while retaining common large quantity");var editedOutput=gp.item(gp.bindings().get(1));editedOutput.addProperty("count",3);gp.writeItem(gp.bindings().get(1),editedOutput);check(giant.getAsJsonObject("out").getAsJsonObject("item").get("count").getAsInt()==3&&!giant.getAsJsonObject("out").has("count"),"Nested output quantity writes to inner native stack");gp.verifyRoundTrip(giant.deepCopy());checks++;
        var aliases=new LayoutMappings.Profile();aliases.category="generic:fixture";aliases.modVersion="1";aliases.shape="test";aliases.width=100;aliases.height=80;aliases.regions.add(new LayoutMappings.Region("/feed@0",0,0,16,16));aliases.regions.add(new LayoutMappings.Region("/feed@0",30,0,16,16));LayoutMappings.check(aliases);checks++;check(!aliases.regions.get(0).regionId().equals(aliases.regions.get(1).regionId()),"Legacy regions acquire distinct stable IDs without changing binding keys");var oldRole=gi.role;gi.role=Role.CENTER;check(CompatFields.basicRole(gi).equals("输入格")&&gi.role==Role.CENTER,"Basic presentation preserves advanced center semantics");gi.role=oldRole;
        var partial=new CompatDefinition("generic:partial","confirmed");var unsupported=partial.add("/opaque","未知原料",Kind.ITEM,Role.INPUT);unsupported.readOnlyReason="requires codec";partial.add("/work","数值",Kind.NUMBER,Role.PARAMETER);var pv=new RecipePresentation(json("{type:'generic:partial',opaque:{custom:true},work:20}"),partial);check(pv.validate().isEmpty(),"One unsupported field does not lock other native parameters");
        check(QuantityMatching.ambiguous(List.of("iron:1","iron:20480"),List.of("iron:1","iron:1"),false),"Collapsed JEI quantities cannot select between different native inputs");check(!QuantityMatching.ambiguous(List.of("iron:2","iron:3"),List.of("iron:3","iron:2"),false),"Displayed exact quantity multiset permits content matching");check(!QuantityMatching.ambiguous(List.of("iron:20480","iron:20480"),List.of("iron:1","iron:1"),true),"Exactly equivalent repeated inputs may use stable order");
        var chanceData=json("{type:'example:crushing',result:[{result:{id:'minecraft:flint',count:1}},{result:{id:'minecraft:flint',count:1},chance:0.5}],opaque:{count:0}}");
        var chanceDefinition=new CompatDefinition("example:crushing","confirmed");var chance=chanceDefinition.add("/result/1/chance","概率",Kind.NUMBER,Role.PARAMETER);
        var invalidSlot=chanceDefinition.add("/opaque","未识别槽位",Kind.ITEM,Role.INPUT);invalidSlot.quantity="count";
        check(!new RecipePresentation(chanceData,chanceDefinition).validate().isEmpty(),"Reproduces whole mapping refusal from an unrelated unresolved slot");
        var ready=MappingConfirmation.prepare(chanceDefinition,chanceData);
        check(new RecipePresentation(chanceData,ready).validate().isEmpty(),"Independent decimal mapping confirms while unknown slot stays read-only");
        check(!ready.fields.get(1).readOnlyReason.isBlank()&&ready.fields.getFirst().readOnlyReason.isBlank(),"Only unresolved slot receives a reason");
        check(chanceDefinition.fields.get(1).readOnlyReason.isBlank(),"Preparing failed or pending confirmation never mutates the previous mapping");
        var chanceView=new RecipePresentation(chanceData,ready);chanceView.verifyRoundTrip(chanceData.deepCopy());checks++;
        var lostChance=chanceData.deepCopy();lostChance.getAsJsonArray("result").get(1).getAsJsonObject().addProperty("chance",1);fails(()->chanceView.verifyRoundTrip(lostChance),"Codec must still preserve independently mapped chance");
        chance.integer=true;fails(()->MappingConfirmation.prepare(chanceDefinition,chanceData),"Invalid explicitly integer scalar is not silently changed into read-only");chance.integer=false;
        var loading=chanceData.deepCopy();loading.add("neoforge:conditions",new JsonArray());check(new CompatibilityAdapter(ready,loading).validate(loading).isEmpty(),"Loading metadata no longer blocks mapping confirmation");
        var firstOutput=new Field("/result/0","产物",Kind.ITEM,Role.OUTPUT);var probabilisticOutput=new Field("/result/1","产物",Kind.ITEM,Role.OUTPUT);probabilisticOutput.probability="chance";
        check(!CompatFields.sameSlotSemantics(firstOutput,probabilisticOutput),"List folding cannot discard probability metadata on a later output");firstOutput.probability="chance";check(CompatFields.sameSlotSemantics(firstOutput,probabilisticOutput),"Equivalent probability semantics may share a list");
        probabilisticOutput.readOnlyReason="unknown representation";check(!CompatFields.sameSlotSemantics(firstOutput,probabilisticOutput),"List folding does not spread a slot-specific read-only limitation");
        return checks;
    }
    private CompatibilityVerification(){}
}
